INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob IEEE nur für Hardware-Standards bekannt ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Software und Netzwerke"}, {"text": "Ja", "correct": false, "because": "Breiter Anwendungsbereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Standard definiert Ethernet in Netzwerken?', 3, '[{"text": "IEEE 802.3", "correct": true, "because": "Ethernet-Spezifikation"}, {"text": "IEEE 802.11", "correct": false, "because": "Wi-Fi"}, {"text": "IEEE 754", "correct": false, "because": "Gleitkomma"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche deckt IEEE in der IT ab?', 5, '[{"text": "Netzwerkstandards", "correct": true, "because": "z. B. 802.x"}, {"text": "Programmierung", "correct": true, "because": "z. B. IEEE 754"}, {"text": "Hardware-Design", "correct": true, "because": "z. B. Bus-Systeme"}, {"text": "Marketing", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) IEEE 802.11 ist Wi-Fi. b) IEEE 802.3 ist für drahtlose Netze.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "802.3 ist Ethernet"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich einen IEEE-Standard für Netzwerke nutze?', 4, '[{"text": "Schichtmodell", "correct": false, "because": "OSI relevant"}, {"text": "Protokollversion", "correct": false, "because": "Definiert Funktion"}, {"text": "Gerätefarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass IEEE 754 nur für Hardware gilt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Gleitkomma in Software"}, {"text": "Ja", "correct": false, "because": "Auch Programmierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Standard hilft mir bei WLAN-Verbindungen?', 3, '[{"text": "IEEE 802.11", "correct": true, "because": "Wi-Fi Spezifikation"}, {"text": "IEEE 802.1", "correct": false, "because": "Bridging"}, {"text": "IEEE 802.15", "correct": false, "because": "Bluetooth"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rollen spielt IEEE in der IT?', 5, '[{"text": "Netzwerkprotokolle", "correct": true, "because": "z. B. 802.x"}, {"text": "Zahlenformate", "correct": true, "because": "z. B. IEEE 754"}, {"text": "Standardisierung", "correct": true, "because": "Globale Normen"}, {"text": "Webdesign", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) IEEE 802.3 Kabel nutzt und b) IEEE 802.11 nur für kleine Netze ist. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "802.11 auch groß"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um IEEE-Standards in einem Netzwerk zu nutzen?', 4, '[{"text": "Kompatible Hardware", "correct": false, "because": "Erforderlich"}, {"text": "Protokollwissen", "correct": false, "because": "Für Implementierung"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist IEEE 802.15 für Ethernet?', 2, '[{"text": "Nein", "correct": true, "because": "Für PAN wie Bluetooth"}, {"text": "Ja", "correct": false, "because": "802.3 ist Ethernet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet IEEE 802.11 in Netzwerken?', 4, '[{"text": "Drahtlose Verbindung", "correct": true, "because": "Wi-Fi ermöglicht"}, {"text": "Mobilität", "correct": true, "because": "Keine Kabel nötig"}, {"text": "Hohe Latenz", "correct": false, "because": "Nicht erwünscht"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass IEEE-Standards nur für große Firmen sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Für alle Netzwerke"}, {"text": "Ja", "correct": false, "because": "Universell nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit IEEE 754 in der Programmierung?', 3, '[{"text": "Einheitliche Gleitkommazahlen", "correct": true, "because": "Standardisiert Darstellung"}, {"text": "Schnellere Schleifen", "correct": false, "because": "Kein Zusammenhang"}, {"text": "Grafikdesign", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) IEEE 802.1 ist für Bridging. b) IEEE 802.3 ist drahtlos.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "802.3 ist kabelgebunden"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik wähle ich für ein drahtloses Netzwerk?', 4, '[{"text": "IEEE 802.11", "correct": true, "because": "Wi-Fi Standard"}, {"text": "IEEE 802.3", "correct": false, "because": "Ethernet"}, {"text": "IEEE 754", "correct": false, "because": "Gleitkomma"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob IEEE 802.15 für große Netze ist?', 2, '[{"text": "Nein", "correct": true, "because": "Für PAN wie Bluetooth"}, {"text": "Ja", "correct": false, "because": "Kleine Reichweite"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen IEEE-Standards nützlich?', 5, '[{"text": "Interoperabilität", "correct": true, "because": "Geräte harmonieren"}, {"text": "Globale Akzeptanz", "correct": true, "because": "Weltweit genutzt"}, {"text": "Hohe Kosten", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist IEEE 802.11 für kabelgebundene Netze?', 3, '[{"text": "Nein", "correct": true, "because": "Wi-Fi ist drahtlos"}, {"text": "Ja", "correct": false, "because": "802.3 ist kabelgebunden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu IEEE 802.3?', 4, '[{"text": "LAN mit Kabeln", "correct": true, "because": "Ethernet Standard"}, {"text": "Drahtloses Büro", "correct": false, "because": "802.11"}, {"text": "Bluetooth Geräte", "correct": false, "because": "802.15"}]');
